CREATE OR REPLACE FUNCTION public.get_event_recap_facts(p_run_id uuid, p_event_key text)
 RETURNS TABLE(scenario_id uuid, version_id uuid, fact_role text, semantic_key text, display_text text, source_url text, copy_kind text)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r public.playthroughs%rowtype; sid uuid; allowed boolean := false; stage text;
BEGIN
 SELECT * INTO r FROM public.playthroughs p WHERE p.playthrough_id=p_run_id AND p.owner_user_id=auth.uid()
 AND p.session_id IS NULL AND coalesce((auth.jwt()->>'is_anonymous')::boolean,false);
 IF NOT FOUND THEN RETURN; END IF;
 stage:=r.employment_state->>'stage';
 IF p_event_key ~ '^D00[1-4]$' THEN
  SELECT m.scenario_id INTO sid FROM public.scenario_library_metadata m JOIN public.scenarios s USING(scenario_id,version_id)
  WHERE m.version_id=r.version_id AND m.library_key=p_event_key AND s.persona_intent=r.persona_id;
  allowed:=CASE p_event_key
   WHEN 'D001' THEN stage IN ('preparation-result','application-result')
   WHEN 'D002' THEN stage='interview-result' AND r.current_day=2
   WHEN 'D003' THEN stage='reapply-result'
   WHEN 'D004' THEN stage='interview-result' AND r.current_day=3 ELSE false END;
 ELSIF p_event_key LIKE 'bill:%' THEN
  SELECT l.scenario_id INTO sid FROM public.playthrough_expenses e JOIN public.scenario_bill_links l USING(expense_id,version_id)
  WHERE e.playthrough_id=r.playthrough_id AND e.playthrough_expense_id=substring(p_event_key from 6)::uuid
   AND e.version_id=r.version_id AND (e.paid_at IS NOT NULL OR e.ignored_at IS NOT NULL);
  allowed:=sid IS NOT NULL;
 ELSE
  sid:=p_event_key::uuid;
  SELECT EXISTS(SELECT 1 FROM public.player_responses pr JOIN public.choices c ON c.choice_id=pr.choice_id
   WHERE pr.playthrough_id=r.playthrough_id AND pr.version_id=r.version_id AND c.version_id=r.version_id AND c.scenario_id=sid) INTO allowed;
 END IF;
 IF NOT coalesce(allowed,false) THEN RETURN; END IF;
 RETURN QUERY SELECT f.scenario_id,f.version_id,f.fact_role,f.semantic_key,f.display_text,f.source_url,f.copy_kind
 FROM public.scenario_fact_copy f WHERE f.scenario_id=sid AND f.version_id=r.version_id AND f.verified
 AND (f.fact_role='general' OR r.cac_support_enabledabled IS TRUE)
 ORDER BY f.fact_role DESC;
END $function$

CREATE OR REPLACE FUNCTION group_private.submit_vote(p_session_id uuid, p_choice_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.group_sessions; member_id uuid;
begin
  if auth.uid() is null or coalesce((auth.jwt()->>'is_anonymous')::boolean, false) = false then
    raise exception 'Anonymous session required' using errcode = '42501';
  end if;
  select * into s from public.group_sessions where session_id = p_session_id for update;
  select participant_id into member_id from public.group_participants
    where session_id = p_session_id and user_id = auth.uid();
  if member_id is null then raise exception 'Vote denied' using errcode = '42501'; end if;
  if s.status <> 'open' or s.round_state <> 'voting' or s.round_deadline <= now() then
    return jsonb_build_object('error', 'Voting has ended for this question.');
  end if;
  if not exists (select 1 from public.choices where choice_id = p_choice_id
    and scenario_id = s.current_scenario_id and version_id = s.version_id) then
    return jsonb_build_object('error', 'That option is not available for this question.');
  end if;
  insert into public.group_votes(session_id, scenario_id, participant_id, choice_id)
  values (s.session_id, s.current_scenario_id, member_id, p_choice_id)
  on conflict (session_id, scenario_id, participant_id) do update
    set choice_id = excluded.choice_id, updated_at = now();
  return group_private.read_session_state(s.session_id);
end
$function$

CREATE OR REPLACE FUNCTION group_private.control_session(p_session_id uuid, p_action text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.group_sessions; next_scenario uuid; next_position integer;
  winner_persona uuid; winner_job uuid; winner_option text; winning_choice public.choices;
begin
  if auth.uid() is null or coalesce((auth.jwt()->>'is_anonymous')::boolean,false)=false then
    raise exception 'Anonymous session required' using errcode='42501';
  end if;
  select * into s from public.group_sessions where session_id=p_session_id for update;
  if s.session_id is null or s.host_user_id is distinct from auth.uid() then
    raise exception 'Session control denied' using errcode='42501';
  end if;
  if p_action='start' then
    if s.status<>'open' or s.round_state<>'lobby' then return jsonb_build_object('error','This session cannot be started.'); end if;
    select persona_id into winner_persona from public.group_participants where session_id=s.session_id
      group by persona_id order by count(*) desc,persona_id limit 1;
    if winner_persona is null then return jsonb_build_object('error','A household vote is required.'); end if;
    delete from public.group_session_questions where session_id=s.session_id;
    insert into public.group_session_questions(session_id,position,scenario_id)
    select s.session_id,row_number() over(order by d.default_day nulls last,lower(d.title),d.scenario_id)::integer,d.scenario_id
    from (select distinct on(lower(q.title),coalesce(q.description,'')) q.scenario_id,q.title,q.description,q.default_day
      from public.scenarios q where q.version_id=s.version_id and (q.persona_intent=winner_persona or q.persona_intent is null)
        and (select count(*) from public.choices c where c.scenario_id=q.scenario_id and c.version_id=s.version_id)>=1
      order by lower(q.title),coalesce(q.description,''),q.scenario_id) d limit 30;
    if (select count(*) from public.group_session_questions where session_id=s.session_id)<>30 then
      return jsonb_build_object('error','A complete 30-day scenario set is unavailable for the winning household.');
    end if;
    update public.group_sessions set selected_persona_id=winner_persona,
      shared_balance=(select general_starting_balance from public.personas where persona_id=winner_persona),
      employment_stage=case when cac_support_enabled then 'preparation' else 'job' end,
      round_type=case when cac_support_enabled then 'preparation' else 'job' end,
      round_state='voting',current_question_number=0,current_scenario_id=null,
      round_deadline=now()+make_interval(secs=>decision_duration_seconds)
    where session_id=s.session_id;
  elsif p_action='end_voting' then
    if s.status<>'open' or s.round_state<>'voting' then return jsonb_build_object('error','Voting is not open.'); end if;
    update public.group_sessions set round_state='results',round_deadline=now() where session_id=s.session_id;
  elsif p_action='next' then
    if s.status<>'open' or s.round_state<>'results' then return jsonb_build_object('error','End voting before moving on.'); end if;
    if s.round_type='preparation' then
      select option_id into winner_option from public.group_employment_votes where session_id=s.session_id and stage='preparation'
        group by option_id order by count(*) desc,option_id limit 1;
      update public.group_sessions set employment_prepared=winner_option='prepare',employment_stage='job',round_type='job',round_state='voting',
        round_deadline=now()+make_interval(secs=>decision_duration_seconds) where session_id=s.session_id;
    elsif s.round_type='job' then
      select job_id into winner_job from public.group_job_votes where session_id=s.session_id
        and (s.employment_attempt=1 or job_id<>s.selected_job_id)
        group by job_id order by count(*) desc,job_id limit 1;
      if winner_job is null then return jsonb_build_object('error','A job vote is required.'); end if;
      delete from public.group_employment_votes where session_id=s.session_id and stage='clothing';
      update public.group_sessions set selected_job_id=winner_job,employment_stage='clothing',round_type='clothing',round_state='voting',
        round_deadline=now()+make_interval(secs=>decision_duration_seconds) where session_id=s.session_id;
    elsif s.round_type='clothing' and s.employment_stage='clothing' then
      select option_id into winner_option from public.group_employment_votes where session_id=s.session_id and stage='clothing'
        group by option_id order by count(*) desc,option_id limit 1;
      if winner_option is null then return jsonb_build_object('error','A clothing vote is required.'); end if;
      if winner_option='purchase' and coalesce(s.shared_balance,0)<60 then return jsonb_build_object('error','The group cannot afford professional clothing.'); end if;
      update public.group_sessions set
        shared_balance=shared_balance-case when winner_option='purchase' then 60 else 0 end,
        clothing_choice=case when winner_option='purchase' then 'purchase' when winner_option='cac' then 'cac' else clothing_choice end,
        interview_hired=(s.employment_attempt=2 or (s.employment_prepared and winner_option<>'current')),
        employment_stage='interview-result',round_state='results',round_deadline=null
      where session_id=s.session_id;
    elsif s.round_type='clothing' and s.employment_stage='interview-result' then
      if s.interview_hired then
        select weekly_gross_income into s.weekly_income from public.jobs where job_id=s.selected_job_id;
        select position,scenario_id into next_position,next_scenario from public.group_session_questions where session_id=s.session_id order by position limit 1;
        update public.group_sessions set weekly_income=s.weekly_income,employment_stage='complete',round_type='scenario',
          current_question_number=next_position,current_scenario_id=next_scenario,round_state='voting',
          round_deadline=now()+make_interval(secs=>decision_duration_seconds) where session_id=s.session_id;
      else
        delete from public.group_job_votes where session_id=s.session_id;
        update public.group_sessions set employment_attempt=2,employment_stage='job',round_type='job',round_state='voting',
          round_deadline=now()+make_interval(secs=>decision_duration_seconds) where session_id=s.session_id;
      end if;
    else
      select c.* into winning_choice from public.group_votes v join public.choices c on c.choice_id=v.choice_id
        where v.session_id=s.session_id and v.scenario_id=s.current_scenario_id
        group by c.choice_id order by count(*) desc,c.choice_id limit 1;
      if winning_choice.choice_id is not null then
        update public.group_sessions set shared_balance=shared_balance+coalesce(winning_choice.balance_change,0)
        where session_id=s.session_id;
      end if;
      select position,scenario_id into next_position,next_scenario from public.group_session_questions
        where session_id=s.session_id and position>s.current_question_number order by position limit 1;
      if next_scenario is null then
        update public.group_sessions set status='closed',round_state='completed',round_deadline=null where session_id=s.session_id;
      else
        update public.group_sessions set current_scenario_id=next_scenario,current_question_number=next_position,
          round_state='voting',round_deadline=now()+make_interval(secs=>decision_duration_seconds) where session_id=s.session_id;
      end if;
    end if;
  elsif p_action='close' then
    update public.group_sessions set status='closed',round_state='completed',round_deadline=null where session_id=s.session_id;
  else return jsonb_build_object('error','Unknown session action.'); end if;
  return group_private.read_session_state(p_session_id);
end
$function$

CREATE OR REPLACE FUNCTION group_private.submit_job_vote(p_session_id uuid, p_job_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.group_sessions; member_id uuid;
begin
  if auth.uid() is null or coalesce((auth.jwt()->>'is_anonymous')::boolean,false)=false then raise exception 'Anonymous session required' using errcode='42501'; end if;
  select * into s from public.group_sessions where session_id=p_session_id for update;
  select participant_id into member_id from public.group_participants where session_id=p_session_id and user_id=auth.uid();
  if member_id is null then raise exception 'Vote denied' using errcode='42501'; end if;
  if s.status<>'open' or s.round_state<>'voting' or s.round_type<>'job' or s.round_deadline<=now() then return jsonb_build_object('error','Job voting has ended.'); end if;
  if not exists(select 1 from public.jobs where job_id=p_job_id and version_id=s.version_id and is_active and is_approved)
     or (s.employment_attempt=2 and p_job_id=s.selected_job_id) then return jsonb_build_object('error','That job is not available.'); end if;
  insert into public.group_job_votes(session_id,participant_id,job_id) values(s.session_id,member_id,p_job_id)
  on conflict(session_id,participant_id) do update set job_id=excluded.job_id,updated_at=now();
  return group_private.read_session_state(p_session_id);
end
$function$

CREATE OR REPLACE FUNCTION group_private.configure_host_session(p_create boolean, p_decision_duration_seconds integer, p_cac_support_enabled boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare result jsonb; sid uuid;
begin
  result := group_private.configure_host_session(p_create, p_decision_duration_seconds);
  if result is null or result ? 'error' then return result; end if;
  sid := (result->>'sessionId')::uuid;
  if p_create then
    update public.group_sessions set cac_support_enabled = p_cac_support_enabled
    where session_id = sid and host_user_id = auth.uid() and round_state = 'lobby';
  end if;
  return group_private.read_session_state(sid);
end
$function$

CREATE OR REPLACE FUNCTION group_private.join_session(p_code text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  s public.group_sessions;
  u uuid := auth.uid();
  n integer;
  member_id uuid;
begin
  if u is null
     or coalesce((auth.jwt()->>'is_anonymous')::boolean, false) = false then
    raise exception 'Anonymous session required' using errcode = '42501';
  end if;

  perform pg_advisory_xact_lock(hashtextextended(u::text, 932));

  insert into group_private.join_attempts values (u, now(), 1)
  on conflict(user_id) do update set
    attempts = case
      when group_private.join_attempts.window_start < now() - interval '1 minute'
        then 1
      else group_private.join_attempts.attempts + 1
    end,
    window_start = case
      when group_private.join_attempts.window_start < now() - interval '1 minute'
        then now()
      else group_private.join_attempts.window_start
    end
  returning attempts into n;

  if n > 10 then
    return jsonb_build_object(
      'error',
      'Too many attempts. Wait one minute and try again.'
    );
  end if;

  select * into s
  from public.group_sessions
  where join_code = upper(btrim(p_code)) and status = 'open'
  for update;

  if s.session_id is null then
    return jsonb_build_object(
      'error',
      'Session unavailable. Check the code with your facilitator and try again.'
    );
  end if;

  if s.host_user_id = u then
    return jsonb_build_object(
      'error',
      'You are hosting this session. Players should join from their own browser.'
    );
  end if;

  insert into public.group_participants(session_id, user_id)
  values (s.session_id, u)
  on conflict(session_id, user_id) do nothing;

  select participant_id into member_id
  from public.group_participants
  where session_id = s.session_id and user_id = u;

  return jsonb_build_object(
    'sessionId', s.session_id,
    'joinCode', s.join_code,
    'status', s.status,
    'currentScenarioId', s.current_scenario_id,
    'createdAt', s.created_at,
    'versionId', s.version_id,
    'decisionDurationSeconds', s.decision_duration_seconds,
    'participantCount', (
      select count(*)::integer
      from public.group_participants
      where session_id = s.session_id
    ),
    'participantId', member_id,
    'isHost', false
  );
end
$function$

CREATE OR REPLACE FUNCTION group_private.submit_employment_vote(p_session_id uuid, p_option_id text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.group_sessions; member_id uuid; allowed boolean;
begin
  if auth.uid() is null or coalesce((auth.jwt()->>'is_anonymous')::boolean,false)=false then
    raise exception 'Anonymous session required' using errcode='42501';
  end if;
  select * into s from public.group_sessions where session_id=p_session_id for update;
  select participant_id into member_id from public.group_participants
    where session_id=p_session_id and user_id=auth.uid();
  if member_id is null then raise exception 'Vote denied' using errcode='42501'; end if;
  allowed := case s.round_type
    when 'preparation' then p_option_id in ('prepare','skip')
    when 'clothing' then
      (s.clothing_choice in ('purchase','cac') and p_option_id='owned') or
      (s.clothing_choice is null and p_option_id in ('purchase','current')) or
      (s.clothing_choice is null and s.cac_support_enabled and p_option_id='cac')
    else false end;
  if s.status<>'open' or s.round_state<>'voting' or s.round_deadline<=now() or not allowed then
    return jsonb_build_object('error','That employment vote is unavailable.');
  end if;
  insert into public.group_employment_votes(session_id,participant_id,stage,option_id)
  values(s.session_id,member_id,s.round_type,p_option_id)
  on conflict(session_id,participant_id,stage) do update set option_id=excluded.option_id,updated_at=now();
  return group_private.read_session_state(p_session_id);
end
$function$

CREATE OR REPLACE FUNCTION public.submit_scenario_decision(p_run_id uuid, p_scenario_id uuid, p_choice_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r public.playthroughs%rowtype; s public.scenarios%rowtype;
 c public.choices%rowtype; prior public.player_responses%rowtype; delta numeric;
BEGIN
 IF auth.uid() IS NULL OR coalesce((auth.jwt()->>'is_anonymous')::boolean,false) IS NOT TRUE THEN RAISE EXCEPTION 'Anonymous participant required'; END IF;
 SELECT * INTO r FROM public.playthroughs WHERE playthrough_id=p_run_id AND owner_user_id=auth.uid() FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Run unavailable'; END IF;
 IF r.current_scenario_id IS DISTINCT FROM p_scenario_id OR r.version_id IS NULL OR r.session_id IS NOT NULL THEN RAISE EXCEPTION 'Scenario unavailable'; END IF;
 SELECT * INTO s FROM public.scenarios WHERE scenario_id=p_scenario_id AND version_id=r.version_id;
 IF NOT FOUND OR (s.persona_intent IS NOT NULL AND s.persona_intent<>r.persona_id) THEN RAISE EXCEPTION 'Scenario edition or persona mismatch'; END IF;
 SELECT * INTO c FROM public.choices WHERE choice_id=p_choice_id AND scenario_id=s.scenario_id AND version_id=r.version_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'Choice edition or scenario mismatch'; END IF;
 SELECT pr.* INTO prior FROM public.player_responses pr JOIN public.choices ch ON ch.choice_id=pr.choice_id
 WHERE pr.playthrough_id=r.playthrough_id AND ch.scenario_id=s.scenario_id ORDER BY pr.answered_at,pr.response_id LIMIT 1;
 IF FOUND THEN
   IF prior.choice_id IS DISTINCT FROM p_choice_id OR prior.version_id IS DISTINCT FROM r.version_id THEN RAISE EXCEPTION 'Scenario already completed'; END IF;
   RETURN jsonb_build_object('run',to_jsonb(r),'response',to_jsonb(prior),'response_text',c.response_text);
 END IF;
 IF r.status IS DISTINCT FROM 'active' OR r.current_balance IS NULL OR r.current_balance::text IN ('NaN','Infinity','-Infinity') OR r.current_balance<>round(r.current_balance,2) THEN RAISE EXCEPTION 'Run not active or invalid balance'; END IF;
 IF (s.schedule_type='scheduled' AND r.current_day IS DISTINCT FROM s.default_day) OR r.current_day=2 OR (r.current_day=3 AND (r.employment_state->>'hiredDay' IS DISTINCT FROM '2' OR r.employment_state->>'stage' IS DISTINCT FROM 'day')) THEN RAISE EXCEPTION 'Not an ordinary scenario day'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.content_versions WHERE version_id=r.version_id AND status='published' AND published_at IS NOT NULL) THEN RAISE EXCEPTION 'Edition unavailable'; END IF;
 -- This slice only supports direct balance effects, not CAC effects or expense settlement.
 IF EXISTS(SELECT 1 FROM public.cac_support_effects WHERE choice_id=c.choice_id) THEN RAISE EXCEPTION 'Unsupported support effect'; END IF;
 IF c.requires_cac AND r.cac_support_enabledabled IS NOT TRUE THEN RAISE EXCEPTION 'CAC choice unavailable'; END IF; delta:=c.balance_change;
 IF delta IS NULL OR delta::text IN ('NaN','Infinity','-Infinity') OR delta<>round(delta,2) THEN RAISE EXCEPTION 'Invalid choice amount'; END IF;
 IF r.current_balance<c.upfront_cost OR r.current_balance+delta<0 THEN
   UPDATE public.playthroughs SET status='ended', employment_state=employment_state || jsonb_build_object('stage','ended','reason','Your household could not afford this choice.') WHERE playthrough_id=r.playthrough_id RETURNING * INTO r;
   RETURN jsonb_build_object('run',to_jsonb(r),'response',null,'response_text','Your household could not afford this choice.');
 END IF;
 UPDATE public.playthroughs SET current_balance=current_balance+delta, employment_state=CASE WHEN c.requires_cac THEN jsonb_set(employment_state,'{assistanceUsed}','true'::jsonb) ELSE employment_state END WHERE playthrough_id=r.playthrough_id RETURNING * INTO r;
 INSERT INTO public.player_responses(response_id,playthrough_id,choice_id,balance_change_applied,balance_after,answered_at,version_id)
 VALUES(gen_random_uuid(),r.playthrough_id,c.choice_id,delta,r.current_balance,clock_timestamp(),r.version_id) RETURNING * INTO prior;
 RETURN jsonb_build_object('run',to_jsonb(r),'response',to_jsonb(prior),'response_text',c.response_text);
END $function$

CREATE OR REPLACE FUNCTION group_private.configure_host_session(p_create boolean, p_decision_duration_seconds integer)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  s public.group_sessions;
  v uuid;
  u uuid := auth.uid();
  participant_count integer;
begin
  if u is null
     or coalesce((auth.jwt()->>'is_anonymous')::boolean, false) = false then
    raise exception 'Anonymous session required' using errcode = '42501';
  end if;

  if p_decision_duration_seconds not in (30, 60, 90, 120) then
    return jsonb_build_object(
      'error',
      'Choose a decision duration of 30, 60, 90, or 120 seconds.'
    );
  end if;

  perform pg_advisory_xact_lock(hashtextextended(u::text, 931));

  select * into s
  from public.group_sessions
  where host_user_id = u and status = 'open';

  if s.session_id is null and p_create then
    select version_id into v
    from public.content_versions
    where status = 'published' and published_at is not null
    order by published_at desc, version_id
    limit 1;

    if v is null then
      return jsonb_build_object(
        'error',
        'No published simulation is available. Please contact the facilitator.'
      );
    end if;

    loop
      begin
        insert into public.group_sessions(
          join_code,
          host_user_id,
          facilitator_user_id,
          current_scenario_id,
          round_deadline,
          status,
          created_at,
          version_id,
          decision_duration_seconds
        ) values (
          upper(substr(replace(gen_random_uuid()::text, '-', ''), 1, 12)),
          u,
          null,
          null,
          null,
          'open',
          now(),
          v,
          p_decision_duration_seconds
        ) returning * into s;
        exit;
      exception when unique_violation then
        null;
      end;
    end loop;
  end if;

  if s.session_id is null then
    return null;
  end if;

  select count(*)::integer into participant_count
  from public.group_participants
  where session_id = s.session_id;

  return jsonb_build_object(
    'sessionId', s.session_id,
    'joinCode', s.join_code,
    'status', s.status,
    'currentScenarioId', s.current_scenario_id,
    'createdAt', s.created_at,
    'versionId', s.version_id,
    'decisionDurationSeconds', s.decision_duration_seconds,
    'participantCount', participant_count,
    'participantId', null,
    'isHost', true
  );
end
$function$

CREATE OR REPLACE FUNCTION public.valid_employment_document(s jsonb)
 RETURNS boolean
 LANGUAGE plpgsql
 IMMUTABLE
 SET search_path TO ''
AS $function$
declare e jsonb; k text; n integer;
begin
 if jsonb_typeof(s) is distinct from 'object' or s->>'engine' is distinct from 'employment-v1'
    or s->'schemaVersion' is distinct from '1'::jsonb
    or jsonb_typeof(s->'revision') is distinct from 'number' or s->>'revision' !~ '^[0-9]+$'
    or jsonb_typeof(s->'receipts') is distinct from 'object'
    or jsonb_typeof(s->'stage') is distinct from 'string' then return false; end if;
 n:=(s->>'revision')::integer;
 if exists(select 1 from jsonb_object_keys(s) key where key not in ('engine','schemaVersion','revision','stage','receipts','prepared','hasEnglishSkills','hasComputerSkills','clothing','targetId','initialTargetId','hiredDay','weeklyIncome','assistanceUsed','history','creditedDays','reason')) then return false; end if;
 for e in select value from jsonb_each(s->'receipts') loop
   if jsonb_typeof(e) is distinct from 'object' or not (e ?& array['action','expectedRevision','revision','day','change','stage'])
      or jsonb_typeof(e->'action') is distinct from 'object'
      or jsonb_typeof(e->'expectedRevision') is distinct from 'number' or e->>'expectedRevision' !~ '^[0-9]+$'
      or jsonb_typeof(e->'revision') is distinct from 'number' or e->>'revision' !~ '^[0-9]+$'
      or jsonb_typeof(e->'day') is distinct from 'number' or e->>'day' !~ '^[0-9]+$'
      or jsonb_typeof(e->'change') is distinct from 'string' or e->>'change' !~ '^-?[0-9]+([.][0-9]{1,2})?$'
      or jsonb_typeof(e->'stage') is distinct from 'string' then return false; end if;
   if (e->>'revision')::integer <> (e->>'expectedRevision')::integer+1
      or (e->>'revision')::integer>n or (e->>'day')::integer not between 1 and 30 then return false; end if;
 end loop;
 if s->>'stage'='uninitialized' then
   return n=0 and s->'receipts'='{}'::jsonb and (select count(*) from jsonb_object_keys(s))=5;
 end if;
 if not (s ?& array['prepared','hasEnglishSkills','hasComputerSkills','assistanceUsed','clothing','targetId','initialTargetId','hiredDay','weeklyIncome','history','creditedDays','reason'])
    or s->>'stage' not in ('board','preparation-result','application-result','day','interview','interview-result','reapply','reapply-result','income','complete','ended') then return false; end if;
 foreach k in array array['prepared','hasEnglishSkills','hasComputerSkills','assistanceUsed'] loop
   if jsonb_typeof(s->k) is distinct from 'boolean' then return false; end if;
 end loop;
 foreach k in array array['targetId','initialTargetId'] loop
   if s->k <> 'null'::jsonb then
     if jsonb_typeof(s->k) is distinct from 'string' then return false; end if;
     perform (s->>k)::uuid;
   end if;
 end loop;
 if s->'reason' <> 'null'::jsonb and jsonb_typeof(s->'reason') is distinct from 'string' then return false; end if;
 if s->'hiredDay' <> 'null'::jsonb and s->'hiredDay' not in ('2'::jsonb,'3'::jsonb) then return false; end if;
 if jsonb_typeof(s->'weeklyIncome') is distinct from 'string' or s->>'weeklyIncome' !~ '^[0-9]+([.][0-9]{1,2})?$'
    or jsonb_typeof(s->'clothing') is distinct from 'string' or s->>'clothing' not in ('none','purchased','cac')
    or jsonb_typeof(s->'history') is distinct from 'array' or jsonb_typeof(s->'creditedDays') is distinct from 'array' then return false; end if;
 for e in select value from jsonb_array_elements(s->'history') loop
   if jsonb_typeof(e) is distinct from 'object' or jsonb_typeof(e->'text') is distinct from 'string'
      or jsonb_typeof(e->'day') is distinct from 'number' or e->>'day' !~ '^[0-9]+$'
      or jsonb_typeof(e->'change') is distinct from 'string' or e->>'change' !~ '^-?[0-9]+([.][0-9]{1,2})?$' then return false; end if;
   if (e->>'day')::integer not between 0 and 30 then return false; end if;
 end loop;
 for e in select value from jsonb_array_elements(s->'creditedDays') loop
   if jsonb_typeof(e) is distinct from 'number' or e::text !~ '^[0-9]+$' then return false; end if;
   if e::text::integer not between 1 and 30 then return false; end if;
 end loop;
 return true;
exception when others then return false;
end $function$

CREATE OR REPLACE FUNCTION public.submit_employment_action(p_run_id uuid, p_request_id uuid, p_revision integer, p_action jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
 r public.playthroughs%rowtype; prev public.playthroughs%rowtype;
 s jsonb; receipt jsonb; st text; a text; choice text;
 j public.jobs%rowtype; persona public.personas%rowtype;
 support boolean; hired boolean; cost numeric; delta numeric := 0;
 day integer; event jsonb; revision integer; next_stage text;
begin
 if auth.uid() is null or coalesce((auth.jwt()->>'is_anonymous')::boolean,false) is not true then
   raise exception 'Participant authentication required';
 end if;
 if p_run_id is null or p_request_id is null or p_revision is null or p_revision<0
    or p_action is null or jsonb_typeof(p_action) is distinct from 'object'
    or jsonb_typeof(p_action->'type') is distinct from 'string' then raise exception 'Invalid request'; end if;
 a:=p_action->>'type';
 if a not in ('initialize','prepare','apply','interview','continue','end') then raise exception 'Invalid action'; end if;
 if exists(select 1 from jsonb_object_keys(p_action) k where k not in ('type',case a when 'initialize' then 'replayOf' when 'apply' then 'jobId' when 'interview' then 'choice' else 'type' end)) then raise exception 'Unexpected action fields'; end if;
 if a='apply' then
   if jsonb_typeof(p_action->'jobId') is distinct from 'string' then raise exception 'Invalid job ID'; end if;
   perform (p_action->>'jobId')::uuid;
 elsif a='initialize' and p_action ? 'replayOf' then
   if jsonb_typeof(p_action->'replayOf') is distinct from 'string' then raise exception 'Invalid replay ID'; end if;
   perform (p_action->>'replayOf')::uuid;
 elsif a='interview' then
   if jsonb_typeof(p_action->'choice') is distinct from 'string' or p_action->>'choice' not in ('purchase','current','cac','owned') then raise exception 'Invalid clothing choice'; end if;
 end if;
 select * into r from public.playthroughs where playthrough_id=p_run_id and owner_user_id=auth.uid() for update;
 if not found or r.owner_user_id is distinct from auth.uid() then raise exception 'Run unavailable'; end if;
 s := r.employment_state;
 -- This branch runs after authentication, request validation and the owned-row
 -- lock, but before employment-specific validation. All other actions, including
 -- initialized end requests, execute the original implementation below unchanged.
 IF a='end' AND jsonb_typeof(s)='object'
 AND (s->>'stage'='uninitialized'
      OR (s->>'stage'='ended' AND NOT (s ? 'prepared'))) THEN
   IF r.session_id IS NOT NULL OR r.current_day IS DISTINCT FROM 1
      OR r.current_job_id IS NOT NULL OR r.current_scenario_id IS NOT NULL
      OR r.cac_support_enabledabled IS NOT NULL OR r.current_balance IS NULL THEN
     RAISE EXCEPTION 'Not a fresh individual run';
   END IF;
   receipt := jsonb_build_object('action',p_action,'expectedRevision',0,
     'revision',1,'day',r.current_day,'change','0','stage','ended');
   IF s->>'stage'='ended' THEN
     IF r.status IS DISTINCT FROM 'ended' THEN RAISE EXCEPTION 'Inconsistent terminal run'; END IF;
     IF p_revision<>0 OR s IS DISTINCT FROM jsonb_build_object(
       'engine','employment-v1','schemaVersion',1,'stage','ended','revision',1,
       'reason','You ended the walkthrough.',
       'receipts',jsonb_build_object(p_request_id::text,receipt)) THEN
       RAISE EXCEPTION 'Run is not active or request identity reused';
     END IF;
     RETURN jsonb_build_object('run',to_jsonb(r),'receipt',receipt);
   END IF;
   IF r.status IS DISTINCT FROM 'active' THEN RAISE EXCEPTION 'Run is not active individual gameplay'; END IF;
   IF s IS DISTINCT FROM jsonb_build_object('engine','employment-v1','schemaVersion',1,
     'revision',0,'stage','uninitialized','receipts','{}'::jsonb) THEN
     RAISE EXCEPTION 'Unsupported fresh employment marker';
   END IF;
   IF p_revision<>0 THEN RAISE EXCEPTION 'Stale revision'; END IF;
   s := s || jsonb_build_object('stage','ended','reason','You ended the walkthrough.',
     'revision',1,'receipts',jsonb_build_object(p_request_id::text,receipt));
   UPDATE public.playthroughs SET status='ended',employment_state=s
   WHERE playthrough_id=p_run_id AND owner_user_id=auth.uid() RETURNING * INTO r;
   IF NOT FOUND THEN RAISE EXCEPTION 'Run unavailable'; END IF;
   RETURN jsonb_build_object('run',to_jsonb(r),'receipt',receipt);
 END IF;

 if not public.valid_employment_document(s) then raise exception 'Unsupported employment document'; end if;
 if s is null or jsonb_typeof(s) <> 'object' or s->>'engine' is distinct from 'employment-v1' or s->'schemaVersion' is distinct from '1'::jsonb
    or jsonb_typeof(s->'receipts') is distinct from 'object'
    or jsonb_typeof(s->'revision') is distinct from 'number'
    or (s->>'revision') !~ '^[0-9]+$' then raise exception 'Unsupported employment state; run unchanged'; end if;
 if exists(select 1 from jsonb_object_keys(s) k where k not in ('engine','schemaVersion','revision','stage','receipts','prepared','hasEnglishSkills','hasComputerSkills','clothing','targetId','initialTargetId','hiredDay','weeklyIncome','assistanceUsed','history','creditedDays','reason')) then raise exception 'Unfamiliar employment document'; end if;
 if exists(select 1 from jsonb_each(s->'receipts') e where jsonb_typeof(e.value->'action') is distinct from 'object' or jsonb_typeof(e.value->'expectedRevision') is distinct from 'number') then raise exception 'Invalid receipts'; end if;
 receipt := s->'receipts'->p_request_id::text;
 if receipt is not null then
   if receipt->'action' is distinct from p_action or (receipt->>'expectedRevision')::integer <> p_revision then raise exception 'Request identity reused'; end if;
   return jsonb_build_object('run',to_jsonb(r),'receipt',receipt);
 end if;
 if not (s ?& array['engine','schemaVersion','revision','stage','receipts']) then raise exception 'Incomplete document'; end if;
 revision := (s->>'revision')::integer;
 if revision <> p_revision then raise exception 'Stale revision'; end if;
 if r.status is distinct from 'active' or r.session_id is not null then raise exception 'Run is not active individual gameplay'; end if;
 st:=s->>'stage'; a:=p_action->>'type'; day:=r.current_day;
 if a='initialize' then
   if st is distinct from 'uninitialized' or revision<>0 or day is distinct from 1 or r.current_balance is null
      or r.current_job_id is not null or r.current_scenario_id is not null
      or r.cac_support_enabledabled is not null then raise exception 'Not a fresh run'; end if;
   select * into persona from public.personas where persona_id=r.persona_id and version_id=r.version_id;
   if not found or persona.has_english_skills is null or persona.has_computer_skills is null then raise exception 'Skills unavailable'; end if;
   if not exists(select 1 from public.content_versions where version_id=r.version_id and status='published' and published_at is not null) then raise exception 'Edition unavailable'; end if;
   if (select count(*) from public.jobs where version_id=r.version_id and is_active and is_approved and needs_english_skills=false and needs_computer_skills=false)<2 then raise exception 'Insufficient eligible catalog'; end if;
   support:=false;
   if p_action->>'replayOf' is not null then
     if (p_action->>'replayOf')::uuid=p_run_id then raise exception 'Invalid replay'; end if;
     select * into prev from public.playthroughs where playthrough_id=(p_action->>'replayOf')::uuid and owner_user_id=auth.uid();
     if not found or prev.owner_user_id is distinct from auth.uid() or prev.status is distinct from 'completed'
        or prev.cac_support_enabledabled is distinct from false
        or not public.valid_employment_document(prev.employment_state)
        or prev.employment_state->>'engine' is distinct from 'employment-v1'
        or prev.employment_state->'schemaVersion' is distinct from '1'::jsonb
        or prev.employment_state->>'stage' is distinct from 'complete' or prev.current_day is distinct from 30 then raise exception 'Replay not eligible'; end if;
     support:=true;
   end if;
   r.cac_support_enabledabled:=support;
   s:=s || jsonb_build_object('stage','board','prepared',false,'hasEnglishSkills',persona.has_english_skills,
     'hasComputerSkills',persona.has_computer_skills,'clothing','none','targetId',null,'initialTargetId',null,
     'hiredDay',null,'weeklyIncome','0.00','assistanceUsed',false,'history','[]'::jsonb,'creditedDays','[]'::jsonb,'reason',null);
 else
   if not (s ?& array['prepared','hasEnglishSkills','hasComputerSkills','assistanceUsed','clothing','history','creditedDays','targetId','initialTargetId','hiredDay','weeklyIncome','reason']) or st is null or st not in ('board','preparation-result','application-result','day','interview','interview-result','reapply','reapply-result','income')
      or day is null or day not between 1 and 30
      or jsonb_typeof(s->'history') is distinct from 'array' or jsonb_typeof(s->'creditedDays') is distinct from 'array'
      or jsonb_typeof(s->'prepared') is distinct from 'boolean' or jsonb_typeof(s->'hasEnglishSkills') is distinct from 'boolean'
      or jsonb_typeof(s->'hasComputerSkills') is distinct from 'boolean' or jsonb_typeof(s->'assistanceUsed') is distinct from 'boolean'
      or jsonb_typeof(s->'clothing') is distinct from 'string' or s->>'clothing' not in ('none','purchased','cac') or r.cac_support_enabledabled is null
      or exists(select 1 from jsonb_array_elements(s->'history') e where jsonb_typeof(e->'text') is distinct from 'string' or jsonb_typeof(e->'day') is distinct from 'number' or jsonb_typeof(e->'change') is distinct from 'string')
      or jsonb_typeof(s->'weeklyIncome') is distinct from 'string' or (s->>'weeklyIncome') !~ '^[0-9]+([.][0-9]{1,2})?$'
      or (s->>'hiredDay' is not null and (s->>'hiredDay') not in ('2','3'))
      or exists(select 1 from jsonb_array_elements(s->'creditedDays') x where jsonb_typeof(x)<>'number' or x::text !~ '^[0-9]+$')
      or r.current_balance is null then raise exception 'Invalid employment structure'; end if;
   if a='prepare' then
     if st<>'board' or not r.cac_support_enabledabled or (s->>'prepared')::boolean then raise exception 'Preparation unavailable'; end if;
     s:=s || '{"prepared":true,"hasEnglishSkills":true,"hasComputerSkills":true,"assistanceUsed":true,"stage":"preparation-result"}';
     event:=jsonb_build_object('text','Completed simulated CAC preparation');
   elsif a='apply' then
     if st not in ('board','reapply') then raise exception 'Application unavailable'; end if;
     select * into j from public.jobs where job_id=(p_action->>'jobId')::uuid and version_id=r.version_id and is_active and is_approved;
     if not found or j.needs_english_skills is null or j.needs_computer_skills is null
        or (j.needs_english_skills and not (s->>'hasEnglishSkills')::boolean)
        or (j.needs_computer_skills and not (s->>'hasComputerSkills')::boolean)
        or (st='reapply' and j.job_id::text=s->>'initialTargetId') then raise exception 'Job unavailable'; end if;
     if st='board' and not exists(select 1 from public.jobs x where x.version_id=r.version_id and x.job_id<>j.job_id and x.is_active and x.is_approved
        and x.needs_english_skills is not null and x.needs_computer_skills is not null
        and (not x.needs_english_skills or (s->>'hasEnglishSkills')::boolean)
        and (not x.needs_computer_skills or (s->>'hasComputerSkills')::boolean)) then raise exception 'No fallback available'; end if;
     s:=s || jsonb_build_object('targetId',j.job_id,'initialTargetId',coalesce(s->>'initialTargetId',j.job_id::text),'stage',case st when 'board' then 'application-result' else 'reapply-result' end);
     event:=jsonb_build_object('text','Applied for '||j.title,'jobId',j.job_id);
   elsif a='interview' then
     choice:=p_action->>'choice';
     if st<>'interview' or day not in (2,3) or choice is null or choice not in ('purchase','current','cac','owned')
       or (s->>'clothing'<>'none' and choice<>'owned') or (s->>'clothing'='none' and choice='owned')
       or (choice='cac' and not r.cac_support_enabledabled) then raise exception 'Clothing unavailable'; end if;
     select * into j from public.jobs where job_id=(s->>'targetId')::uuid and version_id=r.version_id;
     if not found or j.weekly_gross_income is null or j.weekly_gross_income<0 then raise exception 'Target unavailable'; end if;
     cost:=case choice when 'purchase' then 60.00 else 0 end;
     if cost>r.current_balance then
       s:=s || '{"stage":"ended","reason":"You could not afford the selected professional clothing. No purchase was charged."}'; r.status:='ended';
     else
       delta:=-cost;
       s:=s || jsonb_build_object('clothing',case choice when 'purchase' then 'purchased' when 'cac' then 'cac' else s->>'clothing' end,
          'assistanceUsed',(s->>'assistanceUsed')::boolean or choice='cac');
       hired:=day=3 or ((s->>'prepared')::boolean and s->>'clothing'<>'none');
       s:=s || jsonb_build_object('stage','interview-result','hiredDay',case when hired then day else null end,
          'weeklyIncome',case when hired then j.weekly_gross_income::text else '0.00' end);
       if hired then r.current_job_id:=j.job_id; end if;
       event:=jsonb_build_object('text',case when hired then 'Hired as '||j.title else 'First interview did not lead to an offer' end,'choice',choice,'hired',hired);
     end if;
   elsif a='end' then
     s:=s || '{"stage":"ended","reason":"You ended the walkthrough."}'; r.status:='ended';
   elsif a='continue' then
     next_stage:=case st when 'preparation-result' then 'board' when 'application-result' then 'day'
       when 'interview-result' then case when s->>'hiredDay' is null then 'reapply' else 'day' end
       when 'reapply-result' then 'day' when 'income' then 'day' when 'day' then 'day' else null end;
     if next_stage is null then raise exception 'Cannot continue'; end if;
     if st='day' then
       if day=30 then next_stage:='complete';r.status:='completed';
       else
         day:=day+1;
         if s->>'hiredDay' is not null and day>(s->>'hiredDay')::integer and (day-(s->>'hiredDay')::integer)%7=0 then
           if s->'creditedDays' @> jsonb_build_array(day) then raise exception 'Wage already credited'; end if;
           delta:=(s->>'weeklyIncome')::numeric;
           s:=jsonb_set(s,'{creditedDays}',s->'creditedDays'||jsonb_build_array(day));next_stage:='income';
           event:=jsonb_build_object('text','Weekly pay received','jobId',r.current_job_id);
         elsif day=2 or (day=3 and s->>'hiredDay' is null) then next_stage:='interview'; end if;
       end if;
     end if;
     s:=s || jsonb_build_object('stage',next_stage);
   end if;
 end if;
 r.current_balance:=r.current_balance+delta;r.current_day:=day;
 if event is not null then
   s:=jsonb_set(s,'{history}',s->'history'||jsonb_build_array(event||jsonb_build_object('day',case when st in ('board','preparation-result') then 0 else day end,'change',delta::text)));
 end if;
 receipt:=jsonb_build_object('action',p_action,'expectedRevision',p_revision,'revision',revision+1,'day',day,'change',delta::text,'stage',s->>'stage');
 s:=s || jsonb_build_object('revision',revision+1,'receipts',(s->'receipts')||jsonb_build_object(p_request_id::text,receipt));
 update public.playthroughs set employment_state=s,current_balance=r.current_balance,current_day=r.current_day,
   current_job_id=r.current_job_id,cac_support_enabledabled=r.cac_support_enabledabled,status=r.status
 where playthrough_id=p_run_id and owner_user_id=auth.uid() returning * into r;
 if not found then raise exception 'Run unavailable'; end if;
 return jsonb_build_object('run',to_jsonb(r),'receipt',receipt);
end $function$

CREATE OR REPLACE FUNCTION public.start_individual_playthrough(p_persona_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$DECLARE v_version uuid; v_balance numeric; v_id uuid;
BEGIN
 IF auth.uid() IS NULL THEN RAISE EXCEPTION 'Sign in anonymously first'; END IF;
 SELECT p.version_id,coalesce(p.general_starting_balance,0) INTO v_version,v_balance
 FROM public.personas p JOIN public.content_versions v ON v.version_id=p.version_id
 WHERE p.persona_id=p_persona_id AND v.status='published' AND v.published_at IS NOT NULL;
 IF NOT FOUND THEN RAISE EXCEPTION 'Persona is not available'; END IF;
 INSERT INTO public.playthroughs(persona_id,version_id,owner_user_id,current_balance,current_day,status,started_at,session_id,current_scenario_id,current_job_id,employment_state,cac_support_enabledabled)
 VALUES (p_persona_id,v_version,auth.uid(),v_balance,1,'active',now(),NULL,NULL,NULL,NULL,NULL)
 RETURNING playthrough_id INTO v_id;
 RETURN v_id;
END;$function$

CREATE OR REPLACE FUNCTION public.pay_bill(p_run_id uuid, p_occurrence_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r public.playthroughs%rowtype; b public.playthrough_expenses%rowtype; cost numeric;
BEGIN
 IF auth.uid() IS NULL OR coalesce((auth.jwt()->>'is_anonymous')::boolean,false) IS NOT TRUE THEN
   RAISE EXCEPTION 'Anonymous participant required'; END IF;
 SELECT * INTO r FROM public.playthroughs WHERE playthrough_id=p_run_id AND owner_user_id=auth.uid() FOR UPDATE;
 IF NOT FOUND OR r.session_id IS NOT NULL THEN RAISE EXCEPTION 'Bills unavailable'; END IF;
 SELECT * INTO b FROM public.playthrough_expenses WHERE playthrough_expense_id=p_occurrence_id
   AND playthrough_id=r.playthrough_id AND version_id=r.version_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Bill unavailable'; END IF;
 IF b.paid_at IS NOT NULL THEN RETURN jsonb_build_object('run',to_jsonb(r),'bill',to_jsonb(b)); END IF;
 IF r.status IS DISTINCT FROM 'active' OR r.employment_state->>'stage' IS DISTINCT FROM 'day'
 OR r.current_day IS NULL OR r.current_day<b.due_day OR r.current_day>30
 OR r.current_balance IS NULL OR r.current_balance<0 OR r.current_balance>='Infinity'::numeric
 OR r.current_balance<>round(r.current_balance,2) THEN RAISE EXCEPTION 'Bill payment unavailable'; END IF;
 cost:=b.amount_due+CASE WHEN b.ignored_at IS NULL THEN 0 ELSE b.late_fee_amount END;
 IF r.current_balance<cost THEN RAISE EXCEPTION 'Insufficient funds to pay this bill in full'; END IF;
 UPDATE public.playthrough_expenses SET paid_at=clock_timestamp(),paid_day=r.current_day,
   payment_balance_after=r.current_balance-cost WHERE playthrough_expense_id=b.playthrough_expense_id RETURNING * INTO b;
 UPDATE public.playthroughs SET current_balance=current_balance-cost
   WHERE playthrough_id=r.playthrough_id RETURNING * INTO r;
 RETURN jsonb_build_object('run',to_jsonb(r),'bill',to_jsonb(b));
END $function$

CREATE OR REPLACE FUNCTION public.ignore_bill(p_run_id uuid, p_occurrence_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE r public.playthroughs%rowtype; b public.playthrough_expenses%rowtype;
BEGIN
 IF auth.uid() IS NULL OR coalesce((auth.jwt()->>'is_anonymous')::boolean,false) IS NOT TRUE THEN
   RAISE EXCEPTION 'Anonymous participant required'; END IF;
 SELECT * INTO r FROM public.playthroughs WHERE playthrough_id=p_run_id AND owner_user_id=auth.uid() FOR UPDATE;
 IF NOT FOUND OR r.session_id IS NOT NULL THEN RAISE EXCEPTION 'Bills unavailable'; END IF;
 SELECT * INTO b FROM public.playthrough_expenses WHERE playthrough_expense_id=p_occurrence_id
   AND playthrough_id=r.playthrough_id AND version_id=r.version_id FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'Bill unavailable'; END IF;
 IF b.ignored_at IS NOT NULL OR b.paid_at IS NOT NULL THEN
   RETURN jsonb_build_object('run',to_jsonb(r),'bill',to_jsonb(b)); END IF;
 IF r.status IS DISTINCT FROM 'active' OR r.employment_state->>'stage' IS DISTINCT FROM 'day'
 OR r.current_day IS DISTINCT FROM b.due_day THEN RAISE EXCEPTION 'Bill Ignore unavailable'; END IF;
 UPDATE public.playthrough_expenses SET ignored_at=clock_timestamp()
   WHERE playthrough_expense_id=b.playthrough_expense_id RETURNING * INTO b;
 RETURN jsonb_build_object('run',to_jsonb(r),'bill',to_jsonb(b));
END $function$

CREATE OR REPLACE FUNCTION group_private.read_session_state_setup(p_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  base jsonb;
  s public.group_sessions;
  u uuid := auth.uid();
  member_id uuid;
  caller_is_host boolean;
  own_persona uuid;
  own_ready boolean;
  own_household text;
begin
  base := group_private.read_session_state_base(p_session_id);
  if base ? 'error' then return base; end if;

  select * into s from public.group_sessions where session_id = p_session_id;
  caller_is_host := s.host_user_id = u;
  select gp.participant_id, gp.persona_id, gp.is_ready, p.name
    into member_id, own_persona, own_ready, own_household
  from public.group_participants gp
  left join public.personas p on p.persona_id = gp.persona_id
  where gp.session_id = p_session_id and gp.user_id = u;

  return base || jsonb_build_object(
    'householdId', own_persona,
    'householdName', own_household,
    'ready', coalesce(own_ready, false),
    'readyCount', (select count(*)::integer from public.group_participants
      where session_id = p_session_id and is_ready),
    'participants', case when caller_is_host then (
      select coalesce(jsonb_agg(jsonb_build_object(
        'participantId', x.participant_id,
        'alias', 'Participant ' || lpad(x.position::text, 2, '0'),
        'householdId', x.persona_id,
        'householdName', x.household_name,
        'ready', x.is_ready
      ) order by x.position), '[]'::jsonb)
      from (
        select gp.participant_id, gp.persona_id, gp.is_ready, p.name household_name,
          row_number() over (order by gp.joined_at, gp.participant_id) position
        from public.group_participants gp
        left join public.personas p on p.persona_id = gp.persona_id
        where gp.session_id = p_session_id
      ) x
    ) else null end
  );
end
$function$

CREATE OR REPLACE FUNCTION group_private.read_session_state_base(p_session_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  s public.group_sessions;
  u uuid := auth.uid();
  member_id uuid;
  caller_is_host boolean;
  question jsonb;
  total_questions integer;
  votes_cast integer;
begin
  if u is null
     or coalesce((auth.jwt()->>'is_anonymous')::boolean, false) = false then
    raise exception 'Anonymous session required' using errcode = '42501';
  end if;

  select * into s from public.group_sessions where session_id = p_session_id;
  if s.session_id is null then
    return jsonb_build_object('error', 'Session unavailable.');
  end if;

  caller_is_host := s.host_user_id = u;
  select participant_id into member_id
  from public.group_participants
  where session_id = s.session_id and user_id = u;
  if not caller_is_host and member_id is null then
    raise exception 'Session access denied' using errcode = '42501';
  end if;

  select count(*)::integer into total_questions
  from public.group_session_questions where session_id = s.session_id;
  select count(*)::integer into votes_cast
  from public.group_votes
  where session_id = s.session_id and scenario_id = s.current_scenario_id;

  if s.current_scenario_id is not null then
    select jsonb_build_object(
      'scenarioId', q.scenario_id,
      'title', q.title,
      'description', coalesce(q.description, ''),
      'choices', (
        select coalesce(jsonb_agg(jsonb_build_object(
          'choiceId', c.choice_id,
          'text', c.choice_text,
          'voteCount', case when s.round_state in ('results', 'completed')
            then (select count(*) from public.group_votes gv
                  where gv.session_id = s.session_id
                    and gv.scenario_id = q.scenario_id
                    and gv.choice_id = c.choice_id)
            else null end
        ) order by c.choice_id), '[]'::jsonb)
        from public.choices c
        where c.scenario_id = q.scenario_id and c.version_id = s.version_id
      )
    ) into question
    from public.scenarios q where q.scenario_id = s.current_scenario_id;
  end if;

  return jsonb_build_object(
    'sessionId', s.session_id,
    'joinCode', s.join_code,
    'status', s.status,
    'roundState', s.round_state,
    'currentScenarioId', s.current_scenario_id,
    'currentQuestionNumber', s.current_question_number,
    'totalQuestionCount', total_questions,
    'roundDeadline', s.round_deadline,
    'acceptingVotes', s.status = 'open' and s.round_state = 'voting'
      and s.round_deadline > now(),
    'question', question,
    'selectedChoiceId', (
      select choice_id from public.group_votes
      where session_id = s.session_id and scenario_id = s.current_scenario_id
        and participant_id = member_id
    ),
    'voteCount', votes_cast,
    'createdAt', s.created_at,
    'versionId', s.version_id,
    'decisionDurationSeconds', s.decision_duration_seconds,
    'participantCount', (select count(*)::integer from public.group_participants
      where session_id = s.session_id),
    'participantId', member_id,
    'isHost', caller_is_host
  );
end
$function$

CREATE OR REPLACE FUNCTION group_private.update_session_state(p_session_id uuid, p_status text, p_current_scenario_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare
  s public.group_sessions;
  u uuid := auth.uid();
begin
  if u is null
     or coalesce((auth.jwt()->>'is_anonymous')::boolean, false) = false then
    raise exception 'Anonymous session required' using errcode = '42501';
  end if;

  if p_status not in ('open', 'closed') then
    return jsonb_build_object('error', 'Session status must be open or closed.');
  end if;

  select * into s
  from public.group_sessions
  where session_id = p_session_id
  for update;

  if s.session_id is null or s.host_user_id is distinct from u then
    raise exception 'Session update denied' using errcode = '42501';
  end if;

  if s.status = 'closed' then
    if p_status = 'closed'
       and p_current_scenario_id is not distinct from s.current_scenario_id then
      return group_private.read_session_state(s.session_id);
    end if;
    return jsonb_build_object('error', 'This session is closed.');
  end if;

  if p_current_scenario_id is not null and not exists (
    select 1 from public.scenarios q
    where q.scenario_id = p_current_scenario_id
      and q.version_id = s.version_id
  ) then
    return jsonb_build_object(
      'error',
      'The active question does not belong to this session content version.'
    );
  end if;

  update public.group_sessions
  set status = p_status,
      current_scenario_id = p_current_scenario_id
  where session_id = s.session_id;

  return group_private.read_session_state(s.session_id);
end
$function$

CREATE OR REPLACE FUNCTION group_private.update_participant_setup(p_session_id uuid, p_persona_id uuid, p_ready boolean)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare s public.group_sessions; member_id uuid;
begin
  if auth.uid() is null
     or coalesce((auth.jwt()->>'is_anonymous')::boolean, false) = false then
    raise exception 'Anonymous session required' using errcode = '42501';
  end if;
  select * into s from public.group_sessions where session_id = p_session_id for update;
  select participant_id into member_id from public.group_participants
    where session_id = p_session_id and user_id = auth.uid();
  if member_id is null then raise exception 'Setup denied' using errcode = '42501'; end if;
  if s.status <> 'open' or s.round_state <> 'lobby' then
    return jsonb_build_object('error', 'Household settings are locked after the session starts.');
  end if;
  if p_persona_id is not null and not exists (
    select 1 from public.personas where persona_id = p_persona_id
      and version_id = s.version_id
  ) then return jsonb_build_object('error', 'Choose an available household.'); end if;
  if p_ready and p_persona_id is null then
    return jsonb_build_object('error', 'Choose a household before marking ready.');
  end if;
  update public.group_participants set persona_id = p_persona_id, is_ready = p_ready
  where session_id = p_session_id and participant_id = member_id;
  return group_private.read_session_state(p_session_id);
end
$function$
